package com.objectnamemarker;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("objectnamemarker")
public interface ObjectNameMarkerConfig extends Config
{
	@ConfigItem(
			keyName = "hullObjectNames",
			name = "Object hull highlight",
			description = "Object names to render as filled convex hulls. Supports commas, new lines, and # comments.",
			position = 0
	)
	default String hullObjectNames()
	{
		return "";
	}

	@ConfigItem(
			keyName = "outlineObjectNames",
			name = "Object outline highlight",
			description = "Object names to render with model outlines. Supports commas, new lines, and # comments.",
			position = 1
	)
	default String outlineObjectNames()
	{
		return "";
	}

	@ConfigItem(
			keyName = "tileObjectNames",
			name = "Object tile highlight",
			description = "Object names to render tile highlights for. Supports commas, new lines, and # comments.",
			position = 2
	)
	default String tileObjectNames()
	{
		return "";
	}

	@Alpha
	@ConfigItem(
			keyName = "hullColor",
			name = "Hull colour",
			description = "Fill colour for object hull highlights.",
			position = 3
	)
	default Color hullColor()
	{
		return new Color(0, 255, 0, 128);
	}

	@Alpha
	@ConfigItem(
			keyName = "outlineColor",
			name = "Outline colour",
			description = "Colour for object outline highlights.",
			position = 4
	)
	default Color outlineColor()
	{
		return new Color(0, 255, 0);
	}

	@Alpha
	@ConfigItem(
			keyName = "tileFillColor",
			name = "Tile fill colour",
			description = "Fill colour for highlighted tiles.",
			position = 5
	)
	default Color tileFillColor()
	{
		return new Color(0, 255, 0, 128);
	}

	@Alpha
	@ConfigItem(
			keyName = "tileBorderColor",
			name = "Tile border colour",
			description = "Border colour for highlighted tiles.",
			position = 6
	)
	default Color tileBorderColor()
	{
		return new Color(0, 255, 0, 0);
	}

	@ConfigItem(
			keyName = "fadeTileOpacity",
			name = "Fade tile opacity",
			description = "Fade tile fill opacity from the centre/core outward.",
			position = 7
	)
	default boolean fadeTileOpacity()
	{
		return false;
	}

	@Range(min = 1, max = 1000)
	@ConfigItem(
			keyName = "maxHighlightedObjects",
			name = "Max highlighted objects",
			description = "Safety limit for the number of matching objects rendered at once.",
			position = 8
	)
	default int maxHighlightedObjects()
	{
		return 20;
	}

	@Range(min = 1, max = 100)
	@ConfigItem(
			keyName = "renderDistance",
			name = "Render distance",
			description = "Only render matching objects within this many tiles.",
			position = 9
	)
	default int renderDistance()
	{
		return 32;
	}
}

package com.objectnamemarker;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import java.util.Comparator;

class ObjectNameMarkerOverlay extends Overlay
{
    private static final int OUTLINE_WIDTH = 2;
    private static final int OUTLINE_FEATHER = 0;

    private final Client client;
    private final ObjectNameMarkerPlugin plugin;
    private final ObjectNameMarkerConfig config;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject
    private ObjectNameMarkerOverlay(
            Client client,
            ObjectNameMarkerPlugin plugin,
            ObjectNameMarkerConfig config,
            ModelOutlineRenderer modelOutlineRenderer
    )
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.modelOutlineRenderer = modelOutlineRenderer;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(PRIORITY_LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Player localPlayer = client.getLocalPlayer();

        if (localPlayer == null)
        {
            return null;
        }

        WorldPoint playerLocation = localPlayer.getWorldLocation();
        Stroke stroke = new BasicStroke(1);
        List<TileObject> objects = new ArrayList<>(plugin.getObjects());
        objects.sort(Comparator.comparingInt(object -> object.getWorldLocation().distanceTo(playerLocation)));
        int rendered = 0;

        for (TileObject object : objects)
        {
            if (rendered >= config.maxHighlightedObjects())
            {
                break;
            }

            if (object.getWorldLocation().distanceTo(playerLocation) > config.renderDistance())
            {
                continue;
            }

            String objectName = plugin.getObjectName(object);

            if (objectName.isEmpty())
            {
                continue;
            }

            boolean renderedSomething = false;

            if (plugin.getHullObjectNames().contains(objectName))
            {
                renderHull(graphics, object, stroke);
                renderedSomething = true;
            }

            if (plugin.getOutlineObjectNames().contains(objectName))
            {
                renderModelOutline(object);
                renderedSomething = true;
            }

            if (plugin.getTileObjectNames().contains(objectName))
            {
                renderTiles(graphics, object, stroke);
                renderedSomething = true;
            }

            if (renderedSomething)
            {
                rendered++;
            }
        }

        return null;
    }

    private void renderModelOutline(TileObject object)
    {
        if (object instanceof GameObject)
        {
            modelOutlineRenderer.drawOutline((GameObject) object, OUTLINE_WIDTH, config.outlineColor(), OUTLINE_FEATHER);
            return;
        }

        if (object instanceof WallObject)
        {
            modelOutlineRenderer.drawOutline((WallObject) object, OUTLINE_WIDTH, config.outlineColor(), OUTLINE_FEATHER);
            return;
        }

        if (object instanceof DecorativeObject)
        {
            modelOutlineRenderer.drawOutline((DecorativeObject) object, OUTLINE_WIDTH, config.outlineColor(), OUTLINE_FEATHER);
            return;
        }

        if (object instanceof GroundObject)
        {
            modelOutlineRenderer.drawOutline((GroundObject) object, OUTLINE_WIDTH, config.outlineColor(), OUTLINE_FEATHER);
        }
    }

    private void renderHull(Graphics2D graphics, TileObject object, Stroke stroke)
    {
        Shape hull = getConvexHull(object);

        if (hull == null)
        {
            return;
        }

        OverlayUtil.renderPolygon(graphics, hull, config.hullColor(), config.hullColor(), stroke);
    }

    private Shape getConvexHull(TileObject object)
    {
        if (object instanceof GameObject)
        {
            return ((GameObject) object).getConvexHull();
        }

        if (object instanceof WallObject)
        {
            return ((WallObject) object).getConvexHull();
        }

        if (object instanceof DecorativeObject)
        {
            return ((DecorativeObject) object).getConvexHull();
        }

        if (object instanceof GroundObject)
        {
            return ((GroundObject) object).getConvexHull();
        }

        return null;
    }

    private void renderTiles(Graphics2D graphics, TileObject object, Stroke stroke)
    {
        if (object instanceof GameObject)
        {
            renderGameObjectTiles(graphics, (GameObject) object, stroke);
            return;
        }

        renderSingleTileObjectTiles(graphics, object, stroke);
    }

    private void renderGameObjectTiles(Graphics2D graphics, GameObject object, Stroke stroke)
    {
        WorldPoint base = WorldPoint.fromScene(
                client,
                object.getSceneMinLocation().getX(),
                object.getSceneMinLocation().getY(),
                object.getPlane()
        );

        int objectMinX = base.getX();
        int objectMinY = base.getY();
        int objectMaxX = base.getX() + object.sizeX() - 1;
        int objectMaxY = base.getY() + object.sizeY() - 1;

        renderTileArea(
                graphics,
                objectMinX,
                objectMinY,
                objectMaxX,
                objectMaxY,
                object.sizeX(),
                object.sizeY(),
                object.getPlane(),
                stroke
        );
    }

    private void renderSingleTileObjectTiles(Graphics2D graphics, TileObject object, Stroke stroke)
    {
        WorldPoint base = object.getWorldLocation();

        renderTileArea(
                graphics,
                base.getX(),
                base.getY(),
                base.getX(),
                base.getY(),
                1,
                1,
                base.getPlane(),
                stroke
        );
    }

    private void renderTileArea(
            Graphics2D graphics,
            int minX,
            int minY,
            int maxX,
            int maxY,
            int objectWidth,
            int objectHeight,
            int plane,
            Stroke stroke
    )
    {
        CoreRect core = getCoreRect(minX, minY, maxX, maxY);
        boolean canFade = objectWidth >= 3 && objectHeight >= 3;
        int maxDistance = getMaxDistanceFromCore(minX, minY, maxX, maxY, core);

        for (int x = minX; x <= maxX; x++)
        {
            for (int y = minY; y <= maxY; y++)
            {
                LocalPoint localPoint = LocalPoint.fromWorld(client, new WorldPoint(x, y, plane));

                if (localPoint == null)
                {
                    continue;
                }

                Polygon tilePoly = Perspective.getCanvasTilePoly(client, localPoint);

                if (tilePoly == null)
                {
                    continue;
                }

                int distanceFromCore = distanceFromRect(x, y, core.minX, core.minY, core.maxX, core.maxY);
                Color fillColor;
                if (canFade)
                {
                    fillColor = getTileFillColor(distanceFromCore, maxDistance);
                }
                else
                {
                    fillColor = config.tileFillColor();
                }

                OverlayUtil.renderPolygon(
                        graphics,
                        tilePoly,
                        config.tileBorderColor(),
                        fillColor,
                        stroke
                );
            }
        }
    }

    private Color getTileFillColor(int distanceFromCore, int maxDistance)
    {
        Color base = config.tileFillColor();

        if (!config.fadeTileOpacity() || maxDistance <= 0 || distanceFromCore <= 0)
        {
            return base;
        }

        int effectiveMaxDistance = Math.max(maxDistance, 3);

        double t = Math.min(1.0, distanceFromCore / (double) effectiveMaxDistance);
        double alphaMultiplier = 1.0 - (0.5 * t);
        int alpha = (int) Math.round(base.getAlpha() * alphaMultiplier);

        return new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha);
    }

    private int getMaxDistanceFromCore(int minX, int minY, int maxX, int maxY, CoreRect core)
    {
        int maxDistance = distanceFromRect(minX, minY, core.minX, core.minY, core.maxX, core.maxY);
        maxDistance = Math.max(maxDistance, distanceFromRect(maxX, minY, core.minX, core.minY, core.maxX, core.maxY));
        maxDistance = Math.max(maxDistance, distanceFromRect(minX, maxY, core.minX, core.minY, core.maxX, core.maxY));
        maxDistance = Math.max(maxDistance, distanceFromRect(maxX, maxY, core.minX, core.minY, core.maxX, core.maxY));
        return maxDistance;
    }

    private CoreRect getCoreRect(int minX, int minY, int maxX, int maxY)
    {
        return new CoreRect(
                (minX + maxX) / 2,
                (minY + maxY) / 2,
                (minX + maxX + 1) / 2,
                (minY + maxY + 1) / 2
        );
    }

    private int distanceFromRect(int x, int y, int minX, int minY, int maxX, int maxY)
    {
        int dx = 0;

        if (x < minX)
        {
            dx = minX - x;
        }
        else if (x > maxX)
        {
            dx = x - maxX;
        }

        int dy = 0;

        if (y < minY)
        {
            dy = minY - y;
        }
        else if (y > maxY)
        {
            dy = y - maxY;
        }

        return Math.max(dx, dy);
    }

    private static class CoreRect
    {
        private final int minX;
        private final int minY;
        private final int maxX;
        private final int maxY;

        private CoreRect(int minX, int minY, int maxX, int maxY)
        {
            this.minX = minX;
            this.minY = minY;
            this.maxX = maxX;
            this.maxY = maxY;
        }
    }
}

package com.objectnamemarker;

import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;

class ObjectNameMarkerParser
{
    private static final Pattern LEGACY_TILE_SUFFIX = Pattern.compile("[1-9]\\d*");

    static Set<String> parseNames(String input)
    {
        Set<String> names = new HashSet<>();

        for (String token : tokens(input))
        {
            String name = normalizeName(token);

            if (!name.isEmpty())
            {
                names.add(name);
            }
        }

        return names;
    }

    static Set<String> parseTileNames(String input)
    {
        Set<String> names = new HashSet<>();

        for (String token : tokens(input))
        {
            String name = token;
            int separator = token.lastIndexOf(":");

            // Keep legacy name:<positive number> configs working after tile expansion was removed.
            // The number is accepted for compatibility only and never affects rendering.
            if (separator >= 0
                    && LEGACY_TILE_SUFFIX.matcher(token.substring(separator + 1).trim()).matches())
            {
                name = token.substring(0, separator);
            }

            String normalizedName = normalizeName(name);

            if (!normalizedName.isEmpty())
            {
                names.add(normalizedName);
            }
        }

        return names;
    }

    static String normalizeName(String name)
    {
        if (name == null)
        {
            return "";
        }

        return name.trim().toLowerCase();
    }

    private static Set<String> tokens(String input)
    {
        Set<String> tokens = new HashSet<>();

        if (input == null || input.trim().isEmpty())
        {
            return tokens;
        }

        for (String rawLine : input.split("\\R"))
        {
            String line = rawLine.trim();

            int commentIndex = line.indexOf("#");
            if (commentIndex >= 0)
            {
                line = line.substring(0, commentIndex).trim();
            }

            if (line.isEmpty())
            {
                continue;
            }

            for (String token : line.split(","))
            {
                String trimmed = token.trim();

                if (!trimmed.isEmpty())
                {
                    tokens.add(trimmed);
                }
            }
        }

        return tokens;
    }
}

package com.objectnamemarker;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.events.DecorativeObjectDespawned;
import net.runelite.api.events.DecorativeObjectSpawned;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GroundObjectDespawned;
import net.runelite.api.events.GroundObjectSpawned;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
		name = "Object Name Markers",
		description = "Highlight objects by configured object names",
		tags = {"object", "marker", "highlight", "name", "tile"}
)
public class ObjectNameMarkerPlugin extends Plugin
{
	private static final String CONFIG_GROUP = "objectnamemarker";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ObjectNameMarkerOverlay overlay;

	@Inject
	private ObjectNameMarkerConfig config;

	private final Set<TileObject> objects = new HashSet<>();

	private Set<String> hullObjectNames = new HashSet<>();
	private Set<String> outlineObjectNames = new HashSet<>();
	private Set<String> tileObjectNames = new HashSet<>();

	@Provides
	ObjectNameMarkerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ObjectNameMarkerConfig.class);
	}

	@Override
	protected void startUp()
	{
		rebuildMarkers();
		overlayManager.add(overlay);
		rebuildObjectsOnClientThread();
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		objects.clear();
		hullObjectNames.clear();
		outlineObjectNames.clear();
		tileObjectNames.clear();
	}

	Set<TileObject> getObjects()
	{
		return objects;
	}

	Set<String> getHullObjectNames()
	{
		return hullObjectNames;
	}

	Set<String> getOutlineObjectNames()
	{
		return outlineObjectNames;
	}

	Set<String> getTileObjectNames()
	{
		return tileObjectNames;
	}

	String getObjectName(TileObject object)
	{
		if (object == null)
		{
			return "";
		}

		ObjectComposition composition = client.getObjectDefinition(object.getId());

		if (composition == null)
		{
			return "";
		}

		try
		{
			ObjectComposition impostor = composition.getImpostor();

			if (impostor != null)
			{
				composition = impostor;
			}
		}
		catch (RuntimeException ignored)
		{
			// Some objects do not have a valid impostor/transform state.
		}

		String name = composition.getName();

		if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return "";
		}

		return ObjectNameMarkerParser.normalizeName(name);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CONFIG_GROUP.equals(event.getGroup()))
		{
			return;
		}

		rebuildMarkers();
		rebuildObjectsOnClientThread();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			objects.clear();
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			rebuildObjectsOnClientThread();
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		checkObject(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		objects.remove(event.getGameObject());
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		checkObject(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		objects.remove(event.getWallObject());
	}

	@Subscribe
	public void onDecorativeObjectSpawned(DecorativeObjectSpawned event)
	{
		checkObject(event.getDecorativeObject());
	}

	@Subscribe
	public void onDecorativeObjectDespawned(DecorativeObjectDespawned event)
	{
		objects.remove(event.getDecorativeObject());
	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		checkObject(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		objects.remove(event.getGroundObject());
	}

	private void rebuildMarkers()
	{
		hullObjectNames = ObjectNameMarkerParser.parseNames(config.hullObjectNames());
		outlineObjectNames = ObjectNameMarkerParser.parseNames(config.outlineObjectNames());
		tileObjectNames = ObjectNameMarkerParser.parseTileNames(config.tileObjectNames());
	}

	private void rebuildObjectsOnClientThread()
	{
		clientThread.invokeLater(this::rebuildObjects);
	}

	private void rebuildObjects()
	{
		objects.clear();

		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Scene scene = client.getScene();
		Tile[][][] tiles = scene.getTiles();

		for (int plane = 0; plane < tiles.length; plane++)
		{
			for (int x = 0; x < tiles[plane].length; x++)
			{
				for (int y = 0; y < tiles[plane][x].length; y++)
				{
					Tile tile = tiles[plane][x][y];

					if (tile == null)
					{
						continue;
					}

					for (GameObject gameObject : tile.getGameObjects())
					{
						checkObject(gameObject);
					}

					checkObject(tile.getWallObject());
					checkObject(tile.getDecorativeObject());
					checkObject(tile.getGroundObject());
				}
			}
		}
	}

	private void checkObject(TileObject object)
	{
		String objectName = getObjectName(object);

		if (objectName.isEmpty())
		{
			return;
		}

		if (hullObjectNames.contains(objectName)
				|| outlineObjectNames.contains(objectName)
				|| tileObjectNames.contains(objectName))
		{
			objects.add(object);
		}
	}
}

package com.objectnamemarker;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class ObjectNameMarkerParserTest
{
    @Test
    public void stripsLegacyPositiveNumericSuffixesFromTileNames()
    {
        assertEquals(
                Collections.singleton("bank booth"),
                ObjectNameMarkerParser.parseTileNames(
                        "Bank booth:1, Bank booth:2, Bank booth:3, Bank booth:999999999999999999999"
                )
        );
    }

    @Test
    public void leavesNonPositiveAndNonNumericSuffixesAsPartOfTheName()
    {
        assertEquals(
                new HashSet<>(Arrays.asList("bank booth:0", "bank booth:-1", "bank booth:custom")),
                ObjectNameMarkerParser.parseTileNames("Bank booth:0, Bank booth:-1, Bank booth:custom")
        );
    }
}
